<?php
declare(strict_types=1);
namespace App;
use PDO;use Slim\App;use Psr\Http\Message\ServerRequestInterface as Request;use Psr\Http\Message\ResponseInterface as Response;
final class ReviewRoutes{use Support;public static function register(App $app,PDO $db,Auth $auth,array $cfg):void{$access=new Access($db);
$app->get('/api/submissions/{submissionId}/reviewers',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireChair($u,(int)$sub['conference_id']);return Http::json($s,['items'=>self::all($db,'SELECT ra.id assignment_id,ra.status,ra.created_at,u.id reviewer_id,u.name,u.email FROM review_assignments ra JOIN users u ON u.id=ra.reviewer_id WHERE ra.submission_id=? ORDER BY u.name,u.id',[$sub['id']]),'conflicts'=>self::all($db,'SELECT c.user_id,c.reason,u.name FROM conflicts c JOIN users u ON u.id=c.user_id WHERE c.submission_id=? ORDER BY u.name',[$sub['id']])]);});
$app->post('/api/submissions/{submissionId}/reviewers',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireChair($u,(int)$sub['conference_id']);$access->requirePhase((int)$sub['conference_id'],'review');$d=self::body($r);self::required($d,['reviewerId']);$rid=(int)$d['reviewerId'];self::one($db,"SELECT id FROM users WHERE id=? AND role='reviewer'",[$rid],'reviewer_not_found');if(self::all($db,'SELECT 1 FROM conflicts WHERE submission_id=? AND user_id=?',[$sub['id'],$rid]))throw new ApiException(409,'reviewer_conflict','A conflicted user cannot be assigned.');try{$db->beginTransaction();$db->prepare('INSERT INTO review_assignments(submission_id,reviewer_id,assigned_by) VALUES(?,?,?)')->execute([$sub['id'],$rid,$u['id']]);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO reviews(assignment_id) VALUES(?)')->execute([$id]);$db->prepare("UPDATE submissions SET status='under_review' WHERE id=? AND status='submitted'")->execute([$sub['id']]);$db->prepare("INSERT INTO notifications(user_id,type,message,link) VALUES(?,'assignment','A submission was assigned for review.',?)")->execute([$rid,'/assignments/'.$id]);$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'reviewer_assigned','Reviewer assignment updated.')")->execute([$sub['id'],$u['id']]);$db->commit();}catch(\PDOException $e){if($db->inTransaction())$db->rollBack();throw new ApiException(409,'duplicate_assignment','Reviewer is already assigned.');}return Http::json($s,['assignment'=>self::one($db,'SELECT * FROM review_assignments WHERE id=?',[$id])],201);});
$app->delete('/api/submissions/{submissionId}/reviewers/{reviewerId}',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireChair($u,(int)$sub['conference_id']);$access->requirePhase((int)$sub['conference_id'],'review');$st=$db->prepare("DELETE FROM review_assignments WHERE submission_id=? AND reviewer_id=? AND status!='submitted'");$st->execute([$sub['id'],(int)$a['reviewerId']]);if(!$st->rowCount())throw new ApiException(409,'assignment_locked','Assignment is missing or has a submitted review.');return$s->withStatus(204);});
$app->post('/api/submissions/{submissionId}/conflicts',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireChair($u,(int)$sub['conference_id']);$d=self::body($r);self::required($d,['userId','reason']);$uid=(int)$d['userId'];self::one($db,'SELECT id FROM users WHERE id=?',[$uid],'user_not_found');if(self::all($db,'SELECT 1 FROM review_assignments WHERE submission_id=? AND reviewer_id=?',[$sub['id'],$uid]))throw new ApiException(409,'reviewer_already_assigned','Remove the assignment before recording a conflict.');try{$db->prepare('INSERT INTO conflicts(submission_id,user_id,reason,created_by) VALUES(?,?,?,?)')->execute([$sub['id'],$uid,trim($d['reason']),$u['id']]);}catch(\PDOException){throw new ApiException(409,'conflict_exists','Conflict is already recorded.');}$id=(int)$db->lastInsertId();return Http::json($s,['conflict'=>self::one($db,'SELECT * FROM conflicts WHERE id=?',[$id])],201);});

$app->get('/api/review-assignments/{assignmentId}/review',function(Request $r,Response $s,array $a)use($auth,$db){$u=$auth->requireUser($r,['reviewer']);$x=self::assignment($db,(int)$a['assignmentId'],$u);return Http::json($s,['assignment'=>$x,'review'=>self::one($db,'SELECT * FROM reviews WHERE assignment_id=?',[$x['id']])]);});
$app->put('/api/review-assignments/{assignmentId}/review',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['reviewer']);$x=self::assignment($db,(int)$a['assignmentId'],$u);$access->requirePhase((int)$x['conference_id'],'review');$review=self::one($db,'SELECT * FROM reviews WHERE assignment_id=?',[$x['id']]);if($review['status']==='submitted')throw new ApiException(409,'review_locked','Submitted review is locked.');$d=self::body($r);$map=['confidence'=>'confidence','summary'=>'summary','commentsToAuthors'=>'comments_to_authors','confidentialComments'=>'confidential_comments'];$sets=[];$p=[];foreach($map as $in=>$col)if(array_key_exists($in,$d)){$sets[]="$col=?";$p[]=$d[$in];}if(array_key_exists('scores',$d)){if(!is_array($d['scores']))throw new ApiException(422,'validation_failed','Scores must be an object.',['scores'=>'Expected object.']);foreach($d['scores'] as $score)if(!is_numeric($score)||(float)$score<1||(float)$score>5)throw new ApiException(422,'validation_failed','Scores must be between 1 and 5.',['scores'=>'Out of range.']);$sets[]='scores_json=?';$p[]=json_encode($d['scores']);}if(isset($d['confidence'])&&((int)$d['confidence']<1||(int)$d['confidence']>5))throw new ApiException(422,'validation_failed','Confidence must be between 1 and 5.',['confidence'=>'Out of range.']);if(!$sets)throw new ApiException(422,'validation_failed','No review fields supplied.');$sets[]="updated_at=datetime('now')";$p[]=$review['id'];$db->prepare('UPDATE reviews SET '.implode(',',$sets).' WHERE id=?')->execute($p);$db->prepare("UPDATE review_assignments SET status='in_progress' WHERE id=? AND status='assigned'")->execute([$x['id']]);return Http::json($s,['review'=>self::review($db,(int)$review['id'])]);});
$app->post('/api/review-assignments/{assignmentId}/review/submit',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['reviewer']);$x=self::assignment($db,(int)$a['assignmentId'],$u);$access->requirePhase((int)$x['conference_id'],'review');$review=self::one($db,'SELECT * FROM reviews WHERE assignment_id=?',[$x['id']]);if($review['status']==='submitted')return Http::json($s,['review'=>self::review($db,(int)$review['id'])]);$scores=json_decode($review['scores_json'],true);if(!$scores||!$review['confidence']||trim($review['summary'])===''||trim($review['comments_to_authors'])==='')throw new ApiException(422,'review_incomplete','Scores, confidence, summary, and author comments are required.');$db->beginTransaction();$db->prepare("UPDATE reviews SET status='submitted',submitted_at=datetime('now'),updated_at=datetime('now') WHERE id=?")->execute([$review['id']]);$db->prepare("UPDATE review_assignments SET status='submitted' WHERE id=?")->execute([$x['id']]);$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'review_submitted','Review submitted.')")->execute([$x['submission_id'],$u['id']]);$db->commit();return Http::json($s,['review'=>self::review($db,(int)$review['id'])]);});

$app->get('/api/submissions/{submissionId}/rebuttal',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author','reviewer','chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireSubmissionAccess($u,$sub);$rows=self::all($db,'SELECT * FROM rebuttals WHERE submission_id=?',[$sub['id']]);if(!$rows)throw new ApiException(404,'rebuttal_not_found','Rebuttal not found.');return Http::json($s,['rebuttal'=>$rows[0]]);});
$app->put('/api/submissions/{submissionId}/rebuttal',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author']);$sub=$access->submission((int)$a['submissionId']);if(!$access->isAuthor((int)$sub['id'],(int)$u['id']))throw new ApiException(403,'author_access_required','Only submission authors may edit rebuttal.');$access->requirePhase((int)$sub['conference_id'],'rebuttal');$d=self::body($r);self::required($d,['rebuttalText']);$rows=self::all($db,'SELECT * FROM rebuttals WHERE submission_id=?',[$sub['id']]);if($rows&&$rows[0]['status']==='submitted')throw new ApiException(409,'rebuttal_locked','Submitted rebuttal is read-only.');$db->prepare("INSERT INTO rebuttals(submission_id,rebuttal_text) VALUES(?,?) ON CONFLICT(submission_id) DO UPDATE SET rebuttal_text=excluded.rebuttal_text,updated_at=datetime('now')")->execute([$sub['id'],trim($d['rebuttalText'])]);return Http::json($s,['rebuttal'=>self::one($db,'SELECT * FROM rebuttals WHERE submission_id=?',[$sub['id']])]);});
$app->post('/api/submissions/{submissionId}/rebuttal/submit',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author']);$sub=$access->submission((int)$a['submissionId']);if(!$access->isAuthor((int)$sub['id'],(int)$u['id']))throw new ApiException(403,'author_access_required','Only submission authors may submit rebuttal.');$access->requirePhase((int)$sub['conference_id'],'rebuttal');$reb=self::one($db,'SELECT * FROM rebuttals WHERE submission_id=?',[$sub['id']],'rebuttal_not_found');if($reb['status']==='submitted')return Http::json($s,['rebuttal'=>$reb]);$db->prepare("UPDATE rebuttals SET status='submitted',submitted_at=datetime('now'),updated_at=datetime('now') WHERE id=?")->execute([$reb['id']]);$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'rebuttal_submitted','Author rebuttal submitted.')")->execute([$sub['id'],$u['id']]);return Http::json($s,['rebuttal'=>self::one($db,'SELECT * FROM rebuttals WHERE id=?',[$reb['id']])]);});

$app->put('/api/submissions/{submissionId}/decision',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireChair($u,(int)$sub['conference_id']);$access->requirePhase((int)$sub['conference_id'],'decision');$d=self::body($r);self::required($d,['decision','rationale']);if(!in_array($d['decision'],['accept','reject','conditional_accept'],true))throw new ApiException(422,'validation_failed','Unknown decision.',['decision'=>'Use accept, reject, or conditional_accept.']);$existing=self::all($db,'SELECT * FROM decisions WHERE submission_id=?',[$sub['id']]);if($existing&&$existing[0]['released_at'])throw new ApiException(409,'decision_released','Released decision cannot be edited.');$db->prepare("INSERT INTO decisions(submission_id,decision,rationale,conditions,decided_by) VALUES(?,?,?,?,?) ON CONFLICT(submission_id) DO UPDATE SET decision=excluded.decision,rationale=excluded.rationale,conditions=excluded.conditions,decided_by=excluded.decided_by,updated_at=datetime('now')")->execute([$sub['id'],$d['decision'],trim($d['rationale']),trim((string)($d['conditions']??'')),$u['id']]);return Http::json($s,['decision'=>self::one($db,'SELECT * FROM decisions WHERE submission_id=?',[$sub['id']])]);});
$app->post('/api/submissions/{submissionId}/decision/release',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireChair($u,(int)$sub['conference_id']);$access->requirePhase((int)$sub['conference_id'],'decision');$decision=self::one($db,'SELECT * FROM decisions WHERE submission_id=?',[$sub['id']],'decision_not_found');if(!$decision['released_at']){$db->beginTransaction();$db->prepare("UPDATE decisions SET released_at=datetime('now'),updated_at=datetime('now') WHERE id=?")->execute([$decision['id']]);$db->prepare("UPDATE submissions SET status='decided',updated_at=datetime('now') WHERE id=?")->execute([$sub['id']]);$db->prepare("INSERT INTO notifications(user_id,type,message,link) SELECT user_id,'decision',?,? FROM submission_authors WHERE submission_id=?")->execute(['A decision was released for submission '.$sub['id'],'/submissions/'.$sub['id'],$sub['id']]);$db->prepare("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(?,?,'decision_released','Decision released.')")->execute([$sub['id'],$u['id']]);$db->prepare("INSERT INTO audit_events(actor_id,action,entity_type,entity_id) VALUES(?,'release','decision',?)")->execute([$u['id'],$decision['id']]);$db->commit();}return Http::json($s,['decision'=>self::one($db,'SELECT * FROM decisions WHERE id=?',[$decision['id']])]);});
$app->get('/api/submissions/{submissionId}/decision',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author','chair']);$sub=$access->submission((int)$a['submissionId']);if($u['role']==='chair')$access->requireChair($u,(int)$sub['conference_id']);elseif(!$access->isAuthor((int)$sub['id'],(int)$u['id']))throw new ApiException(403,'submission_access_denied','You cannot access this decision.');$d=self::one($db,'SELECT * FROM decisions WHERE submission_id=?',[$sub['id']],'decision_not_found');if($u['role']==='author'&&!$d['released_at'])throw new ApiException(404,'decision_not_found','Decision not found.');return Http::json($s,['decision'=>$d]);});

$app->get('/api/submissions/{submissionId}/view',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author','reviewer','chair']);$sub=$access->submission((int)$a['submissionId']);$access->requireSubmissionAccess($u,$sub);$view=['id'=>$sub['id'],'conferenceId'=>$sub['conference_id'],'title'=>$sub['title'],'abstract'=>$sub['abstract'],'keywords'=>json_decode($sub['keywords_json'],true),'track'=>$sub['track'],'status'=>$sub['status']];if($u['role']!=='reviewer')$view['authors']=self::all($db,'SELECT u.name,u.email,u.affiliation,sa.author_order FROM submission_authors sa JOIN users u ON u.id=sa.user_id WHERE sa.submission_id=? ORDER BY sa.author_order',[$sub['id']]);return Http::json($s,['submission'=>$view]);});
$app->get('/api/reviews/{reviewId}/view',function(Request $r,Response $s,array $a)use($auth,$db,$access){$u=$auth->requireUser($r,['author','reviewer','chair']);$x=self::one($db,'SELECT rv.*,ra.submission_id,ra.reviewer_id,s.conference_id FROM reviews rv JOIN review_assignments ra ON ra.id=rv.assignment_id JOIN submissions s ON s.id=ra.submission_id WHERE rv.id=?',[(int)$a['reviewId']],'review_not_found');if($u['role']==='author'){if(!$access->isAuthor((int)$x['submission_id'],(int)$u['id'])||$x['status']!=='submitted')throw new ApiException(404,'review_not_found','Review not found.');unset($x['reviewer_id'],$x['confidential_comments'],$x['assignment_id']);}elseif($u['role']==='reviewer'){if((int)$x['reviewer_id']!==(int)$u['id'])throw new ApiException(403,'review_access_denied','This review belongs to another reviewer.');unset($x['reviewer_id']);}else{$access->requireChair($u,(int)$x['conference_id']);$x['reviewer']=self::one($db,'SELECT id,name,email FROM users WHERE id=?',[$x['reviewer_id']]);}$scores=json_decode($x['scores_json'],true);unset($x['scores_json']);$x['scores']=$scores;return Http::json($s,['review'=>$x]);});

foreach(['submissions','reviews','decisions'] as $kind)$app->get('/api/conferences/{conferenceId}/exports/'.$kind.'.csv',function(Request $r,Response $s,array $a)use($auth,$db,$access,$kind){$u=$auth->requireUser($r,['chair']);$cid=(int)$a['conferenceId'];$access->requireChair($u,$cid);$conference=$access->conference($cid);$q=$r->getQueryParams();if($kind==='submissions'){$headers=['submission_id','title','track','status'];$sql='SELECT id submission_id,title,track,status FROM submissions WHERE conference_id=?';$p=[$cid];if(trim($q['track']??'')!==''){$sql.=' AND track=?';$p[]=trim($q['track']);}if(trim($q['status']??'')!==''){$sql.=' AND status=?';$p[]=trim($q['status']);}$rows=self::all($db,$sql.' ORDER BY id',$p);}elseif($kind==='reviews'){$headers=['assignment_id','submission_id','status','confidence','scores'];$rows=self::all($db,'SELECT ra.id assignment_id,ra.submission_id,rv.status,rv.confidence,rv.scores_json scores FROM review_assignments ra JOIN submissions sub ON sub.id=ra.submission_id LEFT JOIN reviews rv ON rv.assignment_id=ra.id WHERE sub.conference_id=? ORDER BY ra.id',[$cid]);}else{$headers=['submission_id','decision','released_at'];$rows=self::all($db,'SELECT sub.id submission_id,d.decision,d.released_at FROM submissions sub LEFT JOIN decisions d ON d.submission_id=sub.id WHERE sub.conference_id=? ORDER BY sub.id',[$cid]);}$stream=fopen('php://temp','r+');fputcsv($stream,$headers);foreach($rows as $row)fputcsv($stream,array_map(fn($h)=>$row[$h]??'',$headers));rewind($stream);$s->getBody()->write((string)stream_get_contents($stream));return$s->withHeader('Content-Type','text/csv; charset=utf-8')->withHeader('Content-Disposition','attachment; filename="conference-'.$cid.'-'.$kind.'.csv"');});
}
private static function assignment(PDO $db,int $id,array $u):array{$x=self::one($db,'SELECT ra.*,s.conference_id FROM review_assignments ra JOIN submissions s ON s.id=ra.submission_id WHERE ra.id=?',[$id],'assignment_not_found');if((int)$x['reviewer_id']!==(int)$u['id'])throw new ApiException(403,'assignment_access_denied','This assignment belongs to another reviewer.');return$x;}private static function review(PDO $db,int $id):array{$x=self::one($db,'SELECT * FROM reviews WHERE id=?',[$id]);$x['scores']=json_decode($x['scores_json'],true);unset($x['scores_json']);return$x;}}
